102	  const ax = Math.abs(x), az = Math.abs(z), adz = Math.abs(z - SHZ), ar = Math.abs(ax - RV_X);
103	  let y = LAND;
104	  if (ax >= DR_X) {                                                 // Nguyễn Văn Linh / Võ Văn Kiệt
105	    if (az <= DR_MED) y = Math.max(y, ROAD + 0.3);
106	    else if (az <= DR_SIDE_IN) y = Math.max(y, ROAD + 0.03);
107	    else if (az >= AX_SIDE.z0 && az <= AX_SIDE.z1) y = Math.max(y, ROAD + 0.2);
108	  }
109	  if (ax >= SH_X) {                                                 // Lê Duẩn / Phạm Văn Đồng
110	    if (adz <= SH_MED) y = Math.max(y, ROAD + 0.3);
111	    else if (adz <= SH_LANE_OUT) y = Math.max(y, ROAD + 0.03);
