156	/* ===== Đường tim thân rồng: chép điểm điều khiển body.ts:27-38 và CatmullRomCurve3 centripetal của three (không import three) ===== */
157	export function stSpinePoints(): [number, number][] {
158	  const pts: [number, number][] = [];
159	  const add = (x: number, yr: number) => pts.push([x, deckY(x) + yr]);
160	  add(-366, 11); add(-361, 16); add(-354, 17.5); add(-347, 14); add(-340, 8.5); add(-331, 4.5); add(-316, 3.0); add(-298, 3.4); add(-276, 2.4);
161	  let x0 = -CONFIG.mainTotal / 2; add(x0, -3);
162	  for (const s of CONFIG.mainSpans) {
163	    const rise = CONFIG.spanRise[s];
164	    for (const t of [0.12, 0.28, 0.5, 0.72, 0.88]) add(x0 + s * t, -3 + (rise + 3) * Math.sin(Math.PI * t));
165	    x0 += s; add(x0, -3);
166	  }
167	  add(272, 2.4); add(289, 3.0); add(303, 4.6); add(314, 7.4); add(323, 10.4); add(330, 13);
168	  return pts;
