170	/* Một trục của đa thức Catmull-Rom không đều (giống CubicPoly.initNonuniformCatmullRom của three) */
171	function stCr(a: number, b: number, c: number, d: number, dt0: number, dt1: number, dt2: number, t: number): number {
172	  const t1 = ((b - a) / dt0 - (c - a) / (dt0 + dt1) + (c - b) / dt1) * dt1;
173	  const t2 = ((c - b) / dt1 - (d - b) / (dt1 + dt2) + (d - c) / dt2) * dt1;
174	  const c2 = -3 * b + 3 * c - 2 * t1 - t2, c3 = 2 * b - 2 * c + t1 + t2;
175	  return b + t1 * t + c2 * t * t + c3 * t * t * t;
176	}
177	export function stSpinePoint(pts: [number, number][], t: number, out: { x: number; y: number }): void {
178	  const l = pts.length, p = (l - 1) * t;
179	  let i = Math.floor(p), w = p - i;
180	  if (w === 0 && i === l - 1) { i = l - 2; w = 1; }
181	  const p1 = pts[i], p2 = pts[i + 1];
182	  const p0: [number, number] = i > 0 ? pts[i - 1] : [2 * pts[0][0] - pts[1][0], 2 * pts[0][1] - pts[1][1]];
183	  const p3: [number, number] = i + 2 < l ? pts[i + 2] : [2 * pts[l - 1][0] - pts[l - 2][0], 2 * pts[l - 1][1] - pts[l - 2][1]];
184	  const d = (a: [number, number], b: [number, number]) => Math.pow((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2, 0.25);
185	  let dt0 = d(p0, p1), dt1 = d(p1, p2), dt2 = d(p2, p3);
186	  if (dt1 < 1e-4) dt1 = 1;
187	  if (dt0 < 1e-4) dt0 = dt1;
188	  if (dt2 < 1e-4) dt2 = dt1;
189	  out.x = stCr(p0[0], p1[0], p2[0], p3[0], dt0, dt1, dt2, w);
190	  out.y = stCr(p0[1], p1[1], p2[1], p3[1], dt0, dt1, dt2, w);
191	}
