201	/* Thân / chân vòm / đầu / đuôi rồng trong tầm người: lấy mẫu đường tim, đánh dấu ô x (0,25 m) nơi ống thân (mặt cắt dọc z = 0)
202	   chạm dải [mặt cầu, mặt cầu + dải phân cách + REACH]; gộp ô liền nhau thành hình chữ nhật trên dải phân cách. */
203	function stDragonSolids(): StSolid[] {
204	  const pts = stSpinePoints(), N = 8000, p = { x: 0, y: 0 };
205	  const xs = new Float64Array(N + 1), ys = new Float64Array(N + 1), len = new Float64Array(N + 1);
206	  for (let i = 0; i <= N; i++) {
207	    stSpinePoint(pts, i / N, p); xs[i] = p.x; ys[i] = p.y;
208	    if (i > 0) len[i] = len[i - 1] + Math.hypot(xs[i] - xs[i - 1], ys[i] - ys[i - 1]);
209	  }
210	  const X0 = -400, STEP = 0.25, M = Math.round(800 / STEP) + 1;
211	  const half = new Float64Array(M);                                 // 0 = ô trống, > 0 = nửa bề ngang thân tại ô
212	  for (let i = 0; i <= N; i++) {
213	    const r = stSpineRadius(len[i] / len[N]), rr = 1.03 * r + 0.085;
214	    const g0 = Math.max(0, Math.ceil((xs[i] - rr - X0) / STEP)), g1 = Math.min(M - 1, Math.floor((xs[i] + rr - X0) / STEP));
215	    for (let g = g0; g <= g1; g++) {
216	      const x = X0 + g * STEP, lo = deckY(x), hi = lo + DR_MEDIAN + REACH;
217	      const yb = ys[i] < lo ? lo : ys[i] > hi ? hi : ys[i];
218	      const dx = xs[i] - x, dy = ys[i] - yb;
219	      if (dx * dx + dy * dy < rr * rr && rr > half[g]) half[g] = rr;
220	    }
221	  }
222	  const out: StSolid[] = [];
223	  let cur: StSolid = null, last = -Infinity;
224	  for (let g = 0; g < M; g++) {
225	    if (half[g] === 0) continue;
226	    const x = X0 + g * STEP;
227	    if (cur && x - last <= DR_ARCH_GAP) { cur.x1 = x + STEP; cur.z1 = Math.max(cur.z1, half[g]); cur.z0 = -cur.z1; }
228	    else { cur = { kind: 'rect', x0: x - STEP, x1: x + STEP, z0: -half[g], z1: half[g] }; out.push(cur); }
229	    last = x;
230	  }
231	  return out;
232	}
