30	interface Tree { x: number; y: number; z: number; r: number; palm: boolean; bx: number; bz: number }   // bx, bz: độ lệch ngọn so với gốc thân (chỉ dừa; thân cong bend·trunkWidth theo hướng xoay)
31	function collectTrees(): Tree[] {
