17	const NX = B.x1 - B.x0 + 1, NZ = B.z1 - B.z0 + 1;
18	const node = (x: number, z: number) => (z - B.z0) * NX + (x - B.x0);
19	function bfs(m: StMap, sx: number, sz: number, box = { x0: B.x0, x1: B.x1, z0: B.z0, z1: B.z1 }): Uint8Array {
20	  const seen = new Uint8Array(NX * NZ), q = new Int32Array(NX * NZ);
21	  assert.ok(stValid(m, sx, sz, 0), `điểm đầu BFS (${sx}, ${sz}) phải hợp lệ`);
22	  let h = 0, t = 0; seen[node(sx, sz)] = 1; q[t++] = node(sx, sz);
23	  while (h < t) {
24	    const k = q[h++], x = k % NX + B.x0, z = Math.floor(k / NX) + B.z0;
25	    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
26	      const nx = x + dx, nz = z + dz;
27	      if (nx < box.x0 || nx > box.x1 || nz < box.z0 || nz > box.z1) continue;
28	      const nk = node(nx, nz);
29	      if (seen[nk]) continue;
30	      if (!stValid(m, nx, nz, 0) || !stValid(m, x + dx / 2, z + dz / 2, 0)) continue;
31	      seen[nk] = 1; q[t++] = nk;
32	    }
33	  }
34	  return seen;
35	}
