156	    assert.ok(Math.abs(stGroundY(map, xm, 0) - (deckY(xm) + 0.3)) < 1e-9, 'dải phân cách cao 0,3 m (deck.ts:19)');
157	  }
158	  /* thân rồng chỉ chặn dải phân cách: lòng đường cạnh chân vòm vẫn đi được */
159	  for (const x of feet) assert.equal(stValid(map, x, 8, 0), true, `lòng đường cạnh chân vòm x = ${x}`);
160	});
