163	  const pts = stSpinePoints();
164	  const curve = new THREE.CatmullRomCurve3(pts.map(([x, y]) => new THREE.Vector3(x, y, 0)), false, 'centripetal');
165	  const p = { x: 0, y: 0 };
166	  for (let i = 0; i <= 500; i++) {
167	    const t = i / 500, v = curve.getPoint(t); stSpinePoint(pts, t, p);
168	    assert.ok(Math.abs(v.x - p.x) < 1e-6 && Math.abs(v.y - p.y) < 1e-6, `t = ${t}: (${v.x}, ${v.y}) ≠ (${p.x}, ${p.y})`);
169	  }
