172	test('tim tháp Cầu sông Hàn không hợp lệ; chân chữ A chặn; gờ chắn xe là tường thấp', () => {
173	  assert.equal(stValid(map, 0, SHZ, 0), false);
174	  assert.equal(stValid(map, 0, SHZ, Infinity), false, 'tháp cao vô hạn, nhảy không qua');
175	  for (const s of [-1, 1]) assert.equal(stValid(map, s * 14.5, SHZ, Infinity), false, 'chân chữ A');
176	  const lows = stBuildStructures().filter((s) => s.top !== undefined);
177	  assert.ok(lows.length >= 4, 'gờ chắn xe hai cầu');
